```
The area of the Rectangle is [area] square pixels.
Can rect1 hold rect2? [true/false]
Can rect1 hold rect3? [true/false]
```

Replace `[area]` with the computed area of `rect1`, and `[true/false]` with the boolean result of whether `rect1` can hold `rect2` and `rect3`, respectively.

#[derive(Debug)]
struct Rectangle {
    width: u32,
    height: u32,
}

impl Rectangle {
    fn area(&self) -> u32 {
        self.width * self.height
    }

    fn can_hold(&self, other: &Rectangle) -> bool {
        self.width > other.width && self.height > other.height
    }
}

fn main() {
    let rect1 = Rectangle { width: 30, height: 50 };

    println!("The area of the Rectangle is {} square pixels.",
             rect1.area()
    );

    let rect2 = Rectangle { width: 10, height: 40 };
    let rect3 = Rectangle { width: 60, height: 45 };

    println!("Can rect1 hold rect2? {}", rect1.can_hold(&rect2));
    println!("Can rect1 hold rect3? {}", rect1.can_hold(&rect3));
}

