 We'll do:

   function mergeSort(arr) {
     if (arr.length <= 1) return arr;

     const mid = Math.floor(arr.length / 2);
     const left = mergeSort(arr.slice(0, mid));
     const right = mergeSort(arr.slice(mid));

     return merge(left, right);
   }

   function merge(left, right) {
     let result = [];
     let i = 0, j = 0;

     while (i < left.length && j < right.length) {
        // Compare left[i] and right[j]
        if (left[i].lastName < right[j].lastName) {
          result.push(left[i]);
          i++;
        } else if (left[i].lastName > right[j].lastName) {
          result.push(right[j]);
          j++;
        } else {
          // same lastName, compare firstName
          if (left[i].firstName < right[j].firstName) {
            result.push(left[i]);
            i++;
          } else if (left[i].firstName > right[j].firstName) {
            result.push(right[j]);
            j++;
          } else {
            // If both lastName and firstName are the same, we can push either.
            // But note: the problem doesn't specify what to do in this case, so we keep the order.
            // However, to be stable, we push the left one first.
            result.push(left[i]);
            i++;
          }
        }
     }

     // Add the remaining elements from left or right
     while (i < left.length) {
        result.push(left[i]);
        i++;
     }

     while (j < right.length) {
        result.push(right[j]);
        j++;
     }

     return result;
   }

