/**
 * Study Participant Sorting Algorithm
 * Sorts participants by lastName (ascending), then firstName (ascending)
 * without using built-in Array.sort() method
 */

/**
 * Compare two participants for sorting order
 * @param {Object} a - First participant
 * @param {Object} b - Second participant
 * @returns {number} - Negative if a < b, positive if a > b, 0 if equal
 */
function compareParticipants(a, b) {
  // First compare by lastName
  if (a.lastName < b.lastName) return -1;
  if (a.lastName > b.lastName) return 1;

  // If lastNames are equal, compare by firstName
  if (a.firstName < b.firstName) return -1;
  if (a.firstName > b.firstName) return 1;

  // If both lastName and firstName are equal
  return 0;
}

/**
 * Merge two sorted arrays into one sorted array
 * @param {Array} left - First sorted array
 * @param {Array} right - Second sorted array
 * @returns {Array} - Merged sorted array
 */
function merge(left, right) {
  const result = [];
  let leftIndex = 0;
  let rightIndex = 0;

  // Compare elements from both arrays and add the smaller one to result
  while (leftIndex < left.length && rightIndex < right.length) {
    if (compareParticipants(left[leftIndex], right[rightIndex]) <= 0) {
      result.push(left[leftIndex]);
      leftIndex++;
    } else {
      result.push(right[rightIndex]);
      rightIndex++;
    }
  }

  // Add any remaining elements from left array
  while (leftIndex < left.length) {
    result.push(left[leftIndex]);
    leftIndex++;
  }

  // Add any remaining elements from right array
  while (rightIndex < right.length) {
    result.push(right[rightIndex]);
    rightIndex++;
  }

  return result;
}

/**
 * Merge sort implementation for sorting participants
 * @param {Array} participants - Array of participant objects
 * @returns {Array} - New sorted array of participants
 */
function mergeSort(participants) {
  // Base case: array with 0 or 1 element is already sorted
  if (participants.length <= 1) {
    return participants.slice(); // Return a copy to avoid mutation
  }

  // Find the middle point
  const middle = Math.floor(participants.length / 2);

  // Split the array into left and right halves
  const leftHalf = participants.slice(0, middle);
  const rightHalf = participants.slice(middle);

  // Recursively sort both halves
  const sortedLeft = mergeSort(leftHalf);
  const sortedRight = mergeSort(rightHalf);

  // Merge the sorted halves
  return merge(sortedLeft, sortedRight);
}

/**
 * Main function to sort participants by lastName and firstName
 * @param {Array} participants - Array of participant objects
 * @returns {Array} - New sorted array of participant objects
 */
function sortParticipants(participants) {
  // Validate input
  if (!Array.isArray(participants)) {
    throw new TypeError('Input must be an array');
  }

  if (participants.length === 0) {
    return [];
  }

  // Validate each participant object
  participants.forEach((participant, index) => {
    if (!participant || typeof participant !== 'object') {
      throw new TypeError(`Participant at index ${index} must be an object`);
    }

    if (typeof participant.lastName !== 'string') {
      throw new TypeError(`Participant at index ${index} must have a string lastName`);
    }

    if (typeof participant.firstName !== 'string') {
      throw new TypeError(`Participant at index ${index} must have a string firstName`);
    }
  });

  // Perform merge sort
  return mergeSort(participants);
}

