    // Validate required fields
    if client.Key == "" ||
        client.PassKey == "" ||
        client.TransactionCallback == "" ||
        client.ShortCode == 0 ||
        client.MSISDN == "" {
        return false
    }

    // Validate MSISDN format
    if !isValidMSISDN(client.MSISDN) {
        return false
    }

    // Validate balance
    if client.Balance < 10.00 {
        return false
    }

    // Validate transaction cooldown (24 hours)
    if time.Since(client.LastTransactionTime).Hours() < 24 {
        return false
    }

    return true
