func isValidMSISDN(msisdn string) bool {
    // Clean the number: remove spaces, dashes, parentheses
    reClean := regexp.MustCompile(`[\s\-\(\)]`)
    cleaned := reClean.ReplaceAllString(msisdn, "")

    // Validate international format: optional +, country code (1-3 digits), 9-12 digits
    re := regexp.MustCompile(`^\+?\d{1,3}\d{9,12}$`)
    return re.MatchString(cleaned)
}

